[{"path":"man/scale_linewidth.Rd","url":"https://raw.githubusercontent.com/tidyverse/ggplot2/a6f1a7c845bfe056ef952b839d2fd65b888ab5cd/man/scale_linewidth.Rd","sha256":"07ec948d769e03228b48284d9d5d4399003dc52feab591a1775c5c95c06d8b6b","git_blob":"68cd7609275b985c1e0f11cd43ab6109b0dddc05","bytes":5159,"generated_header":"% Please edit documentation in R/scale-linewidth.R","examples_line":118,"receipt":"evidence/ggplot2/receipts/new-man-scale_linewidth.Rd.json","accessed_utc":"2026-11-24T00:00:05.002943+00:00","examples_text":"\examples{
p <- ggplot(economics, aes(date, unemploy, linewidth = uempmed)) +
  geom_line(lineend = "round")
p
p + scale_linewidth("Duration of\nunemployment")
p + scale_linewidth(range = c(0, 4))

# Binning can sometimes make it easier to match the scaled data to the legend
p + scale_linewidth_binned()

}
\seealso{
The documentation for \link[=aes_linetype_size_shape]{differentiation related aesthetics}.
}
